+	}
+	
+	// Check for protocols with backslashes (e.g., http:\\ or https:\\)
+	if (/^(?:http|https|ftp|ws):\\/.test(decoded)) {
+		return true;
+	}
+	
+	// Check standard URL patterns
+	return URL_PROTOCOL_REGEX.test(decoded) || decoded.startsWith('data:');
