+  const auth = await withAuth(args);
+  
+  if (!auth.user) {
+    // Manual redirect - withAuth doesn't handle this automatically
+    throw redirect('/sign-in');
+  }
+  
+  // Access token is directly available as a property
+  const { accessToken, user, sessionId } = auth;
