+  }
+
+  // Remote
+  let hrefParsed: URL;
+  try {
+    hrefParsed = new URL(url);
+  } catch {
+    return new Response("Not Found", { status: 404 });
+  }
+
+  if (!["http:", "https:"].includes(hrefParsed.protocol)) {
+    return new Response("Not Found", { status: 404 });
